package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class LibraryRefreshPlanTest {
 @Test public void allLibrariesOnceThenInterval(){LibraryRefreshPlan p=new LibraryRefreshPlan();p.prepare("a",List.of("movies","shows","custom","movies"),0);assertEquals("movies",p.next());assertNull(p.next());p.complete("movies",1);assertEquals("shows",p.next());p.complete("shows",2);assertEquals("custom",p.next());p.complete("custom",3);assertFalse(p.waiting());p.prepare("a",List.of("movies"),1000);assertNull(p.next());p.prepare("a",List.of("movies"),300003);assertEquals("movies",p.next());}
 @Test public void accountSwitchAndCancellation(){LibraryRefreshPlan p=new LibraryRefreshPlan();p.prepare("a",List.of("a","b"),0);assertEquals("a",p.next());p.prepare("other",List.of("c"),1);assertEquals("c",p.next());p.complete("a",2);assertNull(p.next());p.cancel(3);p.prepare("other",List.of("c"),4);assertNull(p.next());p.reset();p.prepare("other",List.of("c"),5);assertEquals("c",p.next());}
 @Test public void emptyAndMissingLibrariesAreSafe(){LibraryRefreshPlan p=new LibraryRefreshPlan();p.prepare("a",List.of(),0);assertNull(p.next());assertFalse(p.waiting());p.prepare("a",List.of("new"),300000);assertEquals("new",p.next());}

 @Test public void injectedIntervalsAndDisabledPlan()throws Exception{for(int minutes:new int[]{5,15,60}){long interval=minutes*60000L;LibraryRefreshPlan p=new LibraryRefreshPlan(interval);p.prepare("a",List.of("x"),0);assertEquals("x",p.next());p.complete("x",1);p.prepare("a",List.of("x"),interval);assertNull(p.next());p.prepare("a",List.of("x"),interval+1);assertEquals("x",p.next());}LibraryRefreshPlan p=new LibraryRefreshPlan(0);p.prepare("a",List.of("x"),0);assertNull(p.next());p.prepare("a",List.of("x"),1,300000);assertEquals("x",p.next());p.prepare("a",List.of("x"),2,0);assertNull(p.next());assertFalse(p.waiting());}
 @Test public void mobilePolicyAndStoredIntervals()throws Exception{assertFalse(LibraryRefreshPlan.allowed(0,false,true));assertFalse(LibraryRefreshPlan.allowed(300000,true,false));assertTrue(LibraryRefreshPlan.allowed(300000,true,true));assertTrue(LibraryRefreshPlan.allowed(300000,false,false));assertEquals(900000,LibraryRefreshPlan.intervalMinutes("15"));assertEquals(3600000,LibraryRefreshPlan.intervalMinutes("60"));assertEquals(0,LibraryRefreshPlan.intervalMinutes("0"));assertEquals(300000,LibraryRefreshPlan.intervalMinutes("bad"));}
}
